        int_keys = [
            'lat_degrees',
            'lat_minutes',
            'long_degrees',
            'long_minutes',
        ]

        float_keys = [
            'lat_seconds',
            'long_seconds',
            'altitude',
            'size',
            'precision_horz',
            'precision_vert',
        ]

        direction_keys = ['lat_direction', 'long_direction']

        reasons = []
        for value in data:
            for key in int_keys:
                try:
                    int(value[key])
                    if (
                        (
                            key == 'lat_degrees'
                            and not 0 <= int(value[key]) <= 90
                        )
                        or (
                            key == 'long_degrees'
                            and not 0 <= int(value[key]) <= 180
                        )
                        or (
                            key in ['lat_minutes', 'long_minutes']
                            and not 0 <= int(value[key]) <= 59
                        )
                    ):
                        reasons.append(
                            ValidationReason(
                                f'invalid value for {key} "{value[key]}"',
                                validator_id=self.id,
                            )
                        )
                except KeyError:
                    reasons.append(
                        ValidationReason(f'missing {key}', validator_id=self.id)
                    )
                except ValueError:
                    reasons.append(
                        ValidationReason(
                            f'invalid {key} "{value[key]}"',
                            validator_id=self.id,
                        )
                    )

            for key in float_keys:
                try:
                    float(value[key])
                    if (
                        (
                            key in ['lat_seconds', 'long_seconds']
                            and not 0 <= float(value[key]) <= 59.999
                        )
                        or (
                            key == 'altitude'
                            and not -100000.00
                            <= float(value[key])
                            <= 42849672.95
                        )
                        or (
                            key in ['size', 'precision_horz', 'precision_vert']
                            and not 0 <= float(value[key]) <= 90000000.00
                        )
                    ):
                        reasons.append(
                            ValidationReason(
                                f'invalid value for {key} "{value[key]}"',
                                validator_id=self.id,
                            )
                        )
                except KeyError:
                    reasons.append(
                        ValidationReason(f'missing {key}', validator_id=self.id)
                    )
                except ValueError:
                    reasons.append(
                        ValidationReason(
                            f'invalid {key} "{value[key]}"',
                            validator_id=self.id,
                        )
                    )

            for key in direction_keys:
                try:
                    str(value[key])
                    if key == 'lat_direction' and value[key] not in ['N', 'S']:
                        reasons.append(
                            ValidationReason(
                                f'invalid direction for {key} "{value[key]}"',
                                validator_id=self.id,
                            )
                        )
                    if key == 'long_direction' and value[key] not in ['E', 'W']:
                        reasons.append(
                            ValidationReason(
                                f'invalid direction for {key} "{value[key]}"',
                                validator_id=self.id,
                            )
                        )
                except KeyError:
                    reasons.append(
                        ValidationReason(f'missing {key}', validator_id=self.id)
                    )
        return reasons

